// The desktop backend: the generated Wails bindings (frontend/bindings is generated by
// `wails3 generate bindings`, which `task build` and `task check` run first).
import { Events } from '@wailsio/runtime'
import { DocsService } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/docs'
import { MemoryService } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/mem'
import { ShellService } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/shell'
import type { ChangeSet } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/docs'
import type { Backend } from './backend-types'

export const isWeb = false

export const backend: Backend = {
  getConfig: () => ShellService.GetConfig(),
  setConfig: (patch) => ShellService.SetConfig(patch),
  setSidebarWidth: (width) => ShellService.SetSidebarWidth(width),
  setPanelWidth: (width) => ShellService.SetPanelWidth(width),
  setSidebarCollapsed: (collapsed) => ShellService.SetSidebarCollapsed(collapsed),
  pickFolder: () => ShellService.PickFolder(),
  checkRoot: (abs) => ShellService.CheckRoot(abs),
  checkDocs: (repoRoot, docsDir, roots) => ShellService.CheckDocs(repoRoot, docsDir, roots),
  openExternal: (url) => ShellService.OpenExternal(url),
  openSettingsFile: () => ShellService.OpenSettingsFile(),
  openInVSCode: (path, line) => ShellService.OpenInVSCode(path, line),

  scan: () => DocsService.Scan(),
  rescan: () => DocsService.Rescan(),
  readFile: (path) => DocsService.ReadFile(path),
  loadCache: (parserVersion) => DocsService.LoadCache(parserVersion),
  saveCache: (parserVersion, index) => DocsService.SaveCache(parserVersion, index),
  logTimings: (line) => DocsService.LogTimings(line),
  readBatch: (paths) => DocsService.ReadBatch(paths),
  onDocsChanged: (handler) => Events.On('docs:changed', (e) => handler(e.data as ChangeSet)),

  setMemoryEnabled: (on) => MemoryService.SetEnabled(on),
  onMemory: (handler) =>
    Events.On('mem:changed', (e) => {
      if (typeof e.data === 'number') handler(e.data)
    }),
  onBench: (handler) => {
    const offs = (['open', 'panel'] as const).map((kind) =>
      Events.On(`bench:${kind}`, (e) => {
        if (typeof e.data === 'string') handler(kind, e.data)
      }),
    )
    return () => offs.forEach((off) => off())
  },
}
